import React, { useState } from 'react';
import Login from './pages/Login';
import Home from './pages/Home';
import Dashboard from './pages/Dashboard';
import Profile from './pages/Profile';

export default function App(){
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('home');

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div style={{display:'flex',flexDirection:'column',height:'100vh'}}>
      {/* Nav bar */}
      <div style={{backgroundColor:'#333',color:'#fff',padding:12,display:'flex',gap:12}}>
        <button onClick={()=>setPage('home')} style={{background: page==='home'?'#06f':'#666',color:'#fff',border:'none',padding:8,cursor:'pointer',borderRadius:4}}>Home</button>
        <button onClick={()=>setPage('dashboard')} style={{background: page==='dashboard'?'#06f':'#666',color:'#fff',border:'none',padding:8,cursor:'pointer',borderRadius:4}}>Dashboard</button>
        <button onClick={()=>setPage('profile')} style={{background: page==='profile'?'#06f':'#666',color:'#fff',border:'none',padding:8,cursor:'pointer',borderRadius:4}}>Profile</button>
      </div>
      {/* Page content */}
      <div style={{flex:1,overflow:'auto'}}>
        {page==='home' && <Home user={user} onLogout={()=>setUser(null)} />}
        {page==='dashboard' && <Dashboard user={user} />}
        {page==='profile' && <Profile user={user} onLogout={()=>{setUser(null);setPage('home');}} />}
      </div>
    </div>
  );
}
